// Junta as 2 paginas, dedupe e filtra: FUNIL DE VENDAS (pipeline 2), ultimos 3 dias
// e (rastreio 100% vazio OU tier vazio).
// TIER SO EXISTE NO FUNIL DE VENDAS: nada de outro funil entra aqui, e o pipeline_id
// viaja junto com o item ate o momento da escrita, onde e conferido de novo.
// Resolve tier por REGRA ja aqui: agente de parcerias/indicacao -> Agentes; criacao manual -> Adicao manual.
const FUNIL_VENDAS = 2;
const DIAS = 3;

const F_TIER   = '346353ade45adcb68850667587de1da11b3bdadd';
const F_AGENTE = 'b603f8b2476b87146d418bd7692ca4d2a41f71a1';
const F_ORIGEM = '5eb405ac4c55fa7ed5acf14c3af542d0a72aaeda';
const F_COMO   = 'd99e4d95cb8baef612eacfe88ae62f0f133becf9'; // [QUAL] Como conheceu a Cardápio Web? (interno)
const OPT_COMO_AGP = 1212; // 'Indicação do Ag. de Parcerias' (NAO confundir com 1601 'Indicação de Parceiro')
const TRACK = ['babc9dc70b0254caf284ed9ac6904531bdd2247b', 'fbef9289bf09467ab894d55a0da0785f7d131c92', '1c61ffb7c5c72afcda0aa03ec34a699098fa82a3', 'ce55f714284ac86b8463c672880636db6568e5f8', 'a75682beeaee346f25771516d2f23cdaf4b7745c', '921ee7657991cd504cd859f5b8fd0b47bb8b2ff6'];

const p1 = $('Deals p1').first().json.data || [];
let p2 = [];
try { p2 = $('Deals p2').first().json.data || []; } catch (e) {}

const seen = new Set();
const corte = Date.now() - DIAS * 24 * 60 * 60 * 1000;
const vazio = v => v === null || v === undefined || v === '';
const out = [];

for (const d of [...p1, ...p2]) {
  if (seen.has(d.id)) continue; seen.add(d.id);
  if (Number(d.pipeline_id) !== FUNIL_VENDAS) continue;
  if (new Date(d.add_time).getTime() < corte) continue;

  const cf = d.custom_fields || {};
  const falta_utm  = TRACK.every(k => vazio(cf[k]));
  const falta_tier = vazio(cf[F_TIER]);
  if (!falta_utm && !falta_tier) continue;

  // TRAVA: tier=Adicao manual (id 1566) e definitivo. Uma vez preenchido, NENHUMA regra
  // (Agente de Parcerias, Origem, Como conheceu) pode reavaliar/trocar o tier do deal -
  // falta_tier ja cobre isso (so decide quando cf[F_TIER] esta vazio), este comentario so
  // torna a garantia explicita: pedido dele 31/07, ex. tier=Adicao manual + Como conheceu=
  // Indicacao do Ag. de Parcerias continua Adicao manual, nao vira Agentes.
  let tier_regra = '';
  if (falta_tier) {
    if (!vazio(cf[F_AGENTE]) || cf[F_ORIGEM] === 1582 || cf[F_COMO] === OPT_COMO_AGP) tier_regra = 'Agentes';
    else if (d.origin === 'ManuallyCreated') tier_regra = 'Adição manual';
  }

  const person_id = d.person_id || '';
  if (!person_id && !(falta_tier && tier_regra)) continue;

  out.push({ json: {
    deal_id: d.id,
    pipeline_id: Number(d.pipeline_id),
    person_id,
    tem_pessoa: !!person_id,
    falta_utm,
    falta_tier,
    tier_regra
  } });
}
return out;

// Casa a resposta do Pipedrive PELO ID DA PESSOA (nao por indice) e extrai email + whatsapp normalizado.
// Antes o pareamento era por posicao: bastava o no Pessoa devolver um numero diferente de itens
// (id vazio -> o Pipedrive responde a LISTA de persons, pessoa apagada, erro) para o deal
// herdar o telefone de outro lead. Era a origem dos telefones estranhos do antigo campo fone8.

const soDigitos = v => String(v === null || v === undefined ? '' : v).replace(/\D/g, '');

// Padrao da tabela leads do Supabase: 55 + DDD + 9 + 8 digitos, tudo junto (ex.: 5521976972751)
function normalizaWhats(raw) {
  let d = soDigitos(raw);
  if (!d) return '';
  if (d.startsWith('00')) d = d.slice(2);                     // 0055...
  if (d.length >= 12 && d.startsWith('55')) d = d.slice(2);    // tira o DDI (nao mexe no DDD 55)
  d = d.replace(/^0+/, '');                                   // 0 de operadora / tronco
  if (d.length === 10) {                                      // DDD + 8: celular antigo ganha o 9
    const ddd = d.slice(0, 2), n = d.slice(2);
    if (/^[6-9]/.test(n)) d = ddd + '9' + n;
  }
  if (d.length !== 11) return '';                             // fixo ou numero torto nao serve de chave
  return '55' + d;
}

// so os deals que realmente foram para o no Pessoa
const base = $('Filtra sem origem').all().filter(x => x.json.tem_pessoa);

const porId = {};
for (const it of items) {
  const r = (it.json && it.json.data) ? it.json.data : (it.json || {});
  if (!r || !r.id) continue;                                  // item de erro do no Pessoa
  const emails = r.emails || r.email || [];
  const em = ((emails.find && emails.find(e => e && e.primary)) || emails[0] || {}).value || '';
  const phones = r.phones || r.phone || [];
  const ph = ((phones.find && phones.find(p => p && p.primary)) || phones[0] || {}).value || '';
  porId[String(r.id)] = {
    email: (em && String(em).includes('@')) ? String(em).trim().toLowerCase() : '',
    fone_pd: String(ph || '')
  };
}

const out = [];
for (const b of base) {
  const p = porId[String(b.json.person_id)] || { email: '', fone_pd: '' };
  const whats = normalizaWhats(p.fone_pd);
  const j = Object.assign({}, b.json, { email: p.email, fone_pd: p.fone_pd, whats });
  if (!j.email && !j.whats && !(j.falta_tier && j.tier_regra)) continue;
  out.push({ json: j });
}
return out;

// UTM via RD + tier em camadas: regra de negocio > cf_tier_atual da RD > (desvio) tabela leads do Supabase.
// A resposta da RD e conferida pelo email antes de ser usada - se vier de outro contato, e descartada.
const SRC_OK = ['direto','google','outros','meta','cardapioweb_com','bing','chatgpt','seo','portal_cardapioweb','brave','yahoo','claude','wpp','youtube','ig','tiktok','rd_station_link_na_bio','fb','an'];
const MED_OK = ['direct','organic','paid','paidsearch','referral','social'];
const DERIVA = {direto:'direct', bing:'organic', brave:'organic', yahoo:'organic', seo:'organic',
  meta:'paid', chatgpt:'referral', claude:'referral', cardapioweb_com:'referral', portal_cardapioweb:'referral'};
const MAPA = {'direto':'direto','meta':'meta','facebook':'meta','fb':'fb','ig':'ig','instagram':'ig',
  'www.bing.com':'bing','bing':'bing','search.brave.com':'brave','br.search.yahoo.com':'yahoo',
  'chatgpt.com':'chatgpt','claude.ai':'claude','cardapioweb.com':'cardapioweb_com',
  'www.cardapioweb.com':'cardapioweb_com','lp.cardapioweb.com':'cardapioweb_com',
  'portal.cardapioweb.com':'portal_cardapioweb','rd_station_link_na_bio':'rd_station_link_na_bio',
  'wpp':'wpp','whatsapp':'wpp','www.youtube.com':'youtube','youtube':'youtube','tiktok':'tiktok','seo':'seo'};
const TIER_MAP = {'1':'Tier 1','2':'Tier 2','3.1':'Tier 3.1','3.2':'Tier 3.2','4':'Tier 4','5':'Tier 5'};

const base = $('Extrai email').all();
const out = [];

for (let i = 0; i < items.length; i++) {
  const b = (base[i] || {}).json;
  if (!b) continue;

  const r = items[i].json || {};
  const status = r.statusCode || (r.body ? 200 : 0);
  const c = (status === 200) ? (r.body || r) : {};
  const emailRD = String(c.email || '').trim().toLowerCase();
  // so aceita o contato da RD se ele for mesmo do email que perguntamos
  const rd_ok = status === 200 && !!b.email && (!emailRD || emailRD === b.email);

  let fonte = '', med = '';
  if (b.falta_utm && rd_ok) {
    const raw = String(c.cf_utm_source || '').toLowerCase().trim();
    const gclid = c.cf_gclid || ''; const fbclid = c.cf_fbclid || '';
    const tags = (c.tags || []).map(t => String(t).toLowerCase());
    if (raw) {
      if (/^[0-9]{12,}$/.test(raw)) fonte = 'meta';
      else if (raw.includes('google')) fonte = 'google';
      else fonte = MAPA[raw] || 'outros';
    } else if (fbclid) fonte = 'meta';
    else if (gclid) fonte = 'google';
    else if (tags.some(t => t.includes('origem seo'))) fonte = 'seo';
    else if (tags.some(t => t.includes('origem google'))) fonte = 'google';
    if (fonte && !SRC_OK.includes(fonte)) fonte = '';
    if (fonte) {
      med = String(c.cf_utm_medium || '').trim();
      if (!(med && MED_OK.includes(med))) { med = DERIVA[fonte] || ''; if (!med && fonte === 'google' && (c.cf_gclid || '')) med = 'paidsearch'; }
    }
  }

  let tier = '';
  if (b.falta_tier) {
    tier = b.tier_regra || '';
    if (!tier && rd_ok) {
      const rt = String(c.cf_tier_atual || '').trim().replace(/^tier\s*/i, '');
      if (TIER_MAP[rt]) tier = TIER_MAP[rt];
    }
  }

  const precisa_supa = !!(b.falta_tier && !tier && b.whats);
  const escreve_utm  = !!(b.falta_utm && fonte);
  const precisa_tier = !!(tier || precisa_supa);
  if (!escreve_utm && !precisa_tier) continue;

  out.push({ json: {
    deal_id: b.deal_id,
    pipeline_id: b.pipeline_id,
    escreve_utm, fonte, med,
    camp:   escreve_utm ? String(c.cf_utm_campaign || '').slice(0, 250) : '',
    cont:   escreve_utm ? String(c.cf_utm_content  || '').slice(0, 250) : '',
    gclid:  escreve_utm ? String(c.cf_gclid  || '').slice(0, 250) : '',
    fbclid: escreve_utm ? String(c.cf_fbclid || '').slice(0, 250) : '',
    tier, precisa_tier, precisa_supa,
    whats: b.whats, email: b.email, fone_pd: b.fone_pd
  } });
}
return out;

// Contexto minimo do ramo de tier. Le direto do proprio input, sem buscar item de outro no,
// entao nao depende de pareamento e nao quebra quando um no anterior falha.
// pode_tier = tem rotulo de tier E o deal e do FUNIL DE VENDAS. Sem os dois, nao escreve nada.
const FUNIL_VENDAS = 2;
return items.map(it => {
  const d = it.json || {};
  const tier = d.tier || '';
  return { json: {
    deal_id: d.deal_id,
    pipeline_id: Number(d.pipeline_id),
    tier,
    precisa_supa: !!d.precisa_supa,
    whats: d.whats || '',
    pode_tier: !!tier && Number(d.pipeline_id) === FUNIL_VENDAS
  } };
});

// Casa a linha do Supabase pelo WHATSAPP NORMALIZADO, nao por indice/pareamento:
// se o no devolver zero, uma ou varias linhas, cada deal so pega a linha que e dele.
// A tabela leads mistura '4' e 'Tier 4' (dado migrado x novo) - os dois viram 'Tier 4'.
const FUNIL_VENDAS = 2;
const TIER_MAP = {'1':'Tier 1','2':'Tier 2','3.1':'Tier 3.1','3.2':'Tier 3.2','4':'Tier 4','5':'Tier 5'};
const rotulo = v => {
  const s = String(v === null || v === undefined ? '' : v).trim().replace(/^tier\s*/i, '');
  return TIER_MAP[s] || '';
};

const porWhats = {};
for (const it of items) {
  const r = it.json || {};
  const w = String(r.whatsapp || '').replace(/\D/g, '');
  const t = rotulo(r.tier);
  if (!w || !t) continue;
  if (!porWhats[w]) porWhats[w] = t;
}

const out = [];
for (const c of $('Contexto tier').all()) {
  const d = c.json;
  if (!d.precisa_supa || !d.whats) continue;
  const t = porWhats[d.whats] || '';
  if (!t) continue;
  out.push({ json: {
    deal_id: d.deal_id,
    pipeline_id: Number(d.pipeline_id),
    tier: t,
    pode_tier: Number(d.pipeline_id) === FUNIL_VENDAS
  } });
}
return out;

// Deal sem pessoa nao tem email nem telefone: nao da para consultar RD nem Supabase.
// Ele so chega ate aqui se ja tiver tier resolvido por REGRA - entao vai direto para a escrita.
const FUNIL_VENDAS = 2;
return items.map(it => {
  const d = it.json || {};
  const tier = d.tier_regra || '';
  return { json: {
    deal_id: d.deal_id,
    pipeline_id: Number(d.pipeline_id),
    tier,
    pode_tier: !!tier && Number(d.pipeline_id) === FUNIL_VENDAS
  } };
}).filter(x => x.json.pode_tier);
